def run(work, mutation=None):
    all_sources = dict(STUBS)
    all_sources["ls/augment/com/TestMediaExtended.java"] = TEST.replace("Process.uid=0", "android.os.Process.uid=0")
    for name in PRODUCTION:
        source = (SRC / (name + ".java")).read_text(encoding="utf-8")
        if mutation and name == mutation[0]:
            before, after = mutation[1:3]
            assert source.count(before) == 1, ("mutation must target one actual branch", before)
            source = source.replace(before, after)
        all_sources["ls/augment/com/" + name + ".java"] = source
    files = []
    for name, value in all_sources.items():
        path = work / name; path.parent.mkdir(parents=True, exist_ok=True); path.write_text(value, encoding="utf-8"); files.append(str(path))
    compiled = subprocess.run([str(JDK / "bin/javac.exe"), "-J-Duser.language=en", "-J-Dfile.encoding=UTF-8", "--release", "17", "-encoding", "UTF-8", "-d", str(work / "classes"), *files], capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=45)
    if compiled.returncode: raise AssertionError(compiled.stdout + compiled.stderr)
    return subprocess.run([str(JDK / "bin/java.exe"), "-cp", str(work / "classes"), "ls.augment.com.TestMediaExtended"], capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=45)


def main():
    parser = argparse.ArgumentParser(description=__doc__); parser.add_argument("--negative-controls", action="store_true"); args = parser.parse_args()
    with tempfile.TemporaryDirectory(prefix="duo-media-extended-") as directory:
        result = run(Path(directory)); print(result.stdout, end="")
        if result.returncode: raise AssertionError(result.stderr)
    if not args.negative_controls: return
    changes = [
        ("AtomicWorkbenchMedia", "return packageUid(pkg) == uid ? new Identity(uid, pkg) : null;", "return new Identity(uid, pkg);", "fresh package UID mismatch accepted"),
        ("AtomicWorkbenchMedia", "for (Selection item : all) if (item.source.id.equals(sources.preference())) { best = item; break; }", "// MUTANT: preference ignored", "manual selection did not bind actual requested token"),
        ("AtomicWorkbenchMedia", "controls.setRating(Rating.newHeartRating(desired));", "// MUTANT: no real rating transport", "heart command did not call actual transport"),
        ("AtomicWorkbenchMedia", '!parsed.track.equals(before.getString("track_id", ""))', "false", "stale track reached setRating"),
        ("AtomicWorkbenchMedia", "if (!(value instanceof Integer) || ((Integer) value) != userId) throw new UserChanged();", "// MUTANT: no current-user barrier", "late user change reached legacy control"),
        ("AtomicWorkbenchMedia", "seen.containsKey(request.id) || seen.size() >= MAX_ACTIONS", "seen.size() >= MAX_ACTIONS", "duplicate request dispatched twice"),
        ("AtomicWorkbenchMediaProgress", "known && moving && Float.isFinite(speed)", "known && Float.isFinite(speed)", "paused progress advanced"),
    ]
    for change in changes:
        with tempfile.TemporaryDirectory(prefix="duo-media-negative-") as directory:
            result = run(Path(directory), change)
            if result.returncode == 0 or change[3] not in result.stdout + result.stderr: raise AssertionError(result.stdout + result.stderr)
            print("PASS media negative control: " + change[3])


if __name__ == "__main__": main()
